package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

class LmdbMapGrowthMetricsTest {

	@Test
	void reportsEpisodeAndCoordinationCountersWithStableUnits() {
		MapGrowthMetrics metrics = new MapGrowthMetrics();
		MapGrowthMetrics.Episode first = metrics.startEpisode();
		first.recordForcedInvalidation(2);
		first.recordForcedInvalidation(3);
		MapGrowthMetrics.Episode second = metrics.startEpisode();

		metrics.recordMapResize(LmdbSailStore.MapResizeKind.TRIPLE_STORE, true);
		metrics.recordMapResize(LmdbSailStore.MapResizeKind.VALUE_STORE);
		metrics.recordReplayRequested();
		metrics.recordReplayRequested();
		metrics.recordReplayAccepted();
		metrics.recordAdmissionWait(0);
		metrics.recordAdmissionWait(7_500_000L);

		assertEquals(new MapGrowthMetrics.Snapshot(2, 1, 5, 2, 1, 1, 7_500_000L, 0, 1, 1, 1),
				metrics.snapshot());
	}

	@Test
	void reportsTheCurrentNumberOfBlockedAdmissionWaiters() {
		MapGrowthMetrics metrics = new MapGrowthMetrics();
		metrics.admissionWaitStarted();
		metrics.admissionWaitStarted();
		assertEquals(2, metrics.snapshot().currentAdmissionWaiters());

		metrics.admissionWaitFinished();
		assertEquals(1, metrics.snapshot().currentAdmissionWaiters());
		metrics.admissionWaitFinished();
		assertEquals(0, metrics.snapshot().currentAdmissionWaiters());
	}

	@Test
	@Timeout(value = 5, unit = TimeUnit.SECONDS)
	void coordinatorReportsOneSharedEpisodeReplayAndBothMapResizes(@TempDir Path dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig("spoc,posc")
				.setMapGrowthReadDrainTimeoutMillis(250));
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		MapGrowthMetrics.Snapshot before = backing.growthMetricsSnapshot();
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> true;
		LmdbSailStore.ReadAttemptLease readAttempt = backing.registerReadAttempt(observer);
		Object owner = new Object();
		LmdbSailStore.MapGrowthAttempt growthAttempt = backing.beginMapGrowthAttempt(owner);
		try (growthAttempt; readAttempt) {
			growthAttempt.requestQuiescence(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
			try (LmdbSailStore.MapGrowthAttempt nested = backing.beginMapGrowthAttempt(owner)) {
				nested.markMapResized(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
				nested.markMapResized(LmdbSailStore.MapResizeKind.VALUE_STORE);
			}
		} finally {
			store.shutDown();
		}

		MapGrowthMetrics.Snapshot after = backing.growthMetricsSnapshot();
		assertEquals(before.growthEpisodes() + 1, after.growthEpisodes());
		assertEquals(before.replayRequests() + 1, after.replayRequests());
		assertEquals(before.replayAccepted() + 1, after.replayAccepted());
		assertEquals(before.tripleStoreResizes() + 1, after.tripleStoreResizes());
		assertEquals(before.valueStoreResizes() + 1, after.valueStoreResizes());
	}
}
